const userText = $input.item.json.body.text || '';

const prompt = `You are an expert terminal command assistant. Given a partial command or task description, suggest 3 different terminal commands or completions.

Rules:
- If input looks like a partial command, suggest completions with common flags/options
- If input is a task description, suggest appropriate commands
- Include brief explanations in format: command # explanation
- Focus on bash/zsh commands for Linux/macOS
- Suggest practical, commonly used options

Input: "${userText}"

Return exactly 3 suggestions as a numbered list (1., 2., 3.). Format: command # brief explanation`;

return {
  json: {
    prompt: prompt,
    originalText: userText
  }
};

const response = $input.item.json;
const originalText = $('Construct Prompt').item.json.originalText;

let suggestions = [];

try {
  const generatedText = response.candidates[0].content.parts[0].text;

  // Parse numbered list format
  const lines = generatedText.split('\n').filter(line => line.trim());

  suggestions = lines
    .filter(line => /^\d+\./.test(line.trim()))
    .map(line => line.replace(/^\d+\.\s*/, '').trim())
    .slice(0, 3);

  // Fallback if parsing fails
  if (suggestions.length === 0) {
    suggestions = [
      "ls -lah # list all files with human-readable sizes",
      "find . -name '*.txt' # find all text files recursively",
      "grep -r 'pattern' . # search for pattern in all files"
    ];
  }
} catch (error) {
  suggestions = [
    "ls -lah # list all files with human-readable sizes",
    "find . -name '*.txt' # find all text files recursively",
    "grep -r 'pattern' . # search for pattern in all files"
  ];
}

return {
  json: {
    suggestions: suggestions,
    originalText: originalText
  }
};
